int PointGroupClass::Get_Polygon_Count()
{
	switch (PointMode)
	{
	case TRIS:
		return PointCount;
	case QUADS:
		return PointCount * 2;
	case SCREENSPACE:
		return PointCount;
	}
	return 0;
}

